-- Name: update_timestamp(); Type: FUNCTION; Schema: unix_tenant_202605; Owner: -
--

CREATE FUNCTION unix_tenant_202605.update_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
      BEGIN
        IF to_jsonb(NEW) ? 'update_time' THEN
          NEW := jsonb_populate_record(NEW, jsonb_build_object('update_time', now()));
        ELSIF to_jsonb(NEW) ? 'update_date' THEN
          NEW := jsonb_populate_record(NEW, jsonb_build_object('update_date', now()));
        END IF;
        RETURN NEW;
      END;
      $$;


