    owner_product_key character varying(64),
    owner_device_id character varying(128),
    configuration text DEFAULT '{}'::text NOT NULL,
    CONSTRAINT ck_iot_ind_group_device_owner CHECK ((((owner_scope)::text <> 'DEVICE'::text) OR ((owner_product_key IS NOT NULL) AND ((owner_product_key)::text <> ''::text) AND (owner_device_id IS NOT NULL) AND ((owner_device_id)::text <> ''::text)))),
    CONSTRAINT ck_iot_ind_group_owner_scope CHECK (((owner_scope)::text = ANY (ARRAY[('ENDPOINT'::character varying)::text, ('DEVICE'::character varying)::text])))
);


