    signature_url character varying(500) DEFAULT NULL::character varying,
    min_hardware_version character varying(64) DEFAULT NULL::character varying,
    max_hardware_version character varying(64) DEFAULT NULL::character varying,
    min_software_version character varying(64) DEFAULT NULL::character varying,
    force_upgrade smallint DEFAULT '0'::smallint,
    status character varying(32) DEFAULT 'DRAFT'::character varying,
    release_notes text,
    extra_info text,
    creator_id character varying(64) DEFAULT NULL::character varying,
    create_time timestamp(6) without time zone DEFAULT now(),
    update_time timestamp(6) without time zone DEFAULT now(),
    tenant_id character varying(12) DEFAULT NULL::character varying
);


