--

CREATE TABLE unix_tenant_202605.sys_oss_config (
    config_id bigint NOT NULL,
    provider character varying(32) NOT NULL,
    endpoint character varying(255) DEFAULT NULL::character varying,
    public_endpoint character varying(255) DEFAULT NULL::character varying,
    domain character varying(255) DEFAULT NULL::character varying,
    prefix character varying(255) DEFAULT NULL::character varying,
    access_key character varying(255) DEFAULT NULL::character varying,
    secret_key text,
    bucket_name character varying(128) DEFAULT NULL::character varying,
    region character varying(64) DEFAULT NULL::character varying,
    is_https boolean DEFAULT false,
    active boolean DEFAULT false,
    create_by character varying(64) DEFAULT ''::character varying,
    create_time timestamp(6) without time zone,
    update_by character varying(64) DEFAULT ''::character varying,
    update_time timestamp(6) without time zone,
    remark character varying(500) DEFAULT ''::character varying,
    tenant_id character varying(64),
    CONSTRAINT ck_sys_oss_config_tenant_not_reserved CHECK (((tenant_id IS NULL) OR (lower(btrim((tenant_id)::text)) <> ALL (ARRAY['system'::text, 'public'::text, 'scada-system'::text])))),
    CONSTRAINT ck_sys_oss_config_tenant_not_system CHECK (((tenant_id IS NULL) OR (lower(btrim((tenant_id)::text)) <> 'system'::text)))
);


