--
-- Name: video_ai_algorithm_task; Type: TABLE; Schema: unix_tenant_202605; Owner: -
--

CREATE TABLE unix_tenant_202605.video_ai_algorithm_task (
    id bigint NOT NULL,
    task_code character varying(128) NOT NULL,
    task_name character varying(128) NOT NULL,
    task_type character varying(32) NOT NULL,
    algorithm_type character varying(32) DEFAULT 'DETECTION'::character varying,
    model_id bigint NOT NULL,
    runtime_node_id bigint,
    runtime_node_code character varying(128),
    runtime_node_name character varying(128),
    runtime_base_url character varying(800),
    runtime_task_id character varying(128),
    stream_protocol character varying(32),
    stream_url character varying(1200),
    stream_name character varying(128),
    source_type character varying(32) DEFAULT 'DIRECT_URL'::character varying,
    source_ref_id character varying(128),
    source_camera_name character varying(128),
    snapshot_input_json text,
    frame_extractor_id bigint,
    frame_extractor_config text,
    result_sorter_id bigint,
    result_sorter_config text,
    roi_json text,
    alarm_rule_json text,
    schedule_json text,
    advanced_params_json text,
    status character varying(32) DEFAULT 'PENDING'::character varying,
    progress integer DEFAULT 0,
    stream_state character varying(32) DEFAULT 'IDLE'::character varying,
    last_snapshot_url character varying(800),
    last_result_at timestamp without time zone,
    last_heartbeat timestamp without time zone,
    error_message text,
    started_at timestamp without time zone,
    stopped_at timestamp without time zone,
    finished_at timestamp without time zone,
    tenant_id character varying(64),
    creator_id character varying(64),
    create_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted smallint DEFAULT 0,
    source_config_json text,
    stream_sources_json text,
    executor_type character varying(64) DEFAULT 'ONNXRUNTIME'::character varying,
    model_format character varying(32) DEFAULT 'ONNX'::character varying,
    device character varying(64) DEFAULT 'auto'::character varying,
    "precision" character varying(16) DEFAULT 'FP32'::character varying,
    target_fps double precision DEFAULT 1,
    batch_size integer DEFAULT 1,
    max_queue_size integer DEFAULT 8,
    frame_drop_policy character varying(32) DEFAULT 'KEEP_LATEST'::character varying,
    resource_request_json text,
    runtime_metrics_json text,
    ai_stream_enabled smallint DEFAULT 0,
    ai_media_server_id bigint,
    ai_media_server_code character varying(128),
    ai_media_server_name character varying(128),
    ai_stream_app character varying(128) DEFAULT 'nexiot-ai'::character varying,
    ai_stream_name character varying(256),
    ai_stream_push_url character varying(1200),
    ai_stream_play_url character varying(1200),
    ai_stream_urls_json text,
    ai_stream_config_json text,
    ai_output_released smallint DEFAULT 1 NOT NULL
);


