--
-- Name: video_ai_dataset_capture_job; Type: TABLE; Schema: unix_tenant_202605; Owner: -
--

CREATE TABLE unix_tenant_202605.video_ai_dataset_capture_job (
    id bigint NOT NULL,
    dataset_id bigint NOT NULL,
    job_code character varying(128) NOT NULL,
    job_name character varying(128) NOT NULL,
    capture_mode character varying(32) DEFAULT 'RTSP_STREAM'::character varying,
    runtime_task_id character varying(128),
    runtime_node_id bigint,
    runtime_node_code character varying(128),
    runtime_node_name character varying(128),
    runtime_base_url character varying(800),
    algorithm_task_id bigint,
    source_type character varying(64),
    source_ref_id character varying(255),
    source_key character varying(128),
    source_camera_name character varying(128),
    source_fingerprint character varying(128),
    stream_protocol character varying(32) DEFAULT 'RTSP'::character varying,
    stream_name character varying(128),
    stream_url_masked character varying(1000),
    stream_sources_json text,
    source_config_json text,
    proxy_owner character varying(32) DEFAULT 'CAPTURE_JOB'::character varying,
    proxy_media_server_id bigint,
    proxy_app character varying(128),
    proxy_stream character varying(128),
    proxy_play_url character varying(1000),
    proxy_json text,
    extractor_json text,
    quality_json text,
    auto_label_json text,
    split_type character varying(32) DEFAULT 'train'::character varying,
    target_fps numeric(8,3),
    interval_seconds numeric(8,3),
    max_frames integer,
    duration_seconds integer,
    captured_count integer DEFAULT 0,
    promoted_count integer DEFAULT 0,
    duplicate_count integer DEFAULT 0,
    status character varying(32) DEFAULT 'PENDING'::character varying,
    progress integer DEFAULT 0,
    stream_state character varying(32) DEFAULT 'IDLE'::character varying,
    error_message character varying(1000),
    log_text text,
    started_at timestamp without time zone,
    stopped_at timestamp without time zone,
    finished_at timestamp without time zone,
    tenant_id character varying(64),
    creator_id character varying(64),
    create_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted smallint DEFAULT 0,
    source_secret_cipher text,
    replaces_job_id bigint,
    active_source_key character varying(255),
    proxy_released smallint DEFAULT 0
);


