    bucket character varying(128),
    object_key character varying(500),
    item_url character varying(800),
    annotations_json text,
    width integer,
    height integer,
    file_size bigint,
    source_type character varying(32) DEFAULT 'UPLOAD'::character varying,
    split_type character varying(32) DEFAULT 'train'::character varying,
    completed smallint DEFAULT 0,
    modification_count integer DEFAULT 0,
    last_modified timestamp without time zone,
    tenant_id character varying(64),
    creator_id character varying(64),
    create_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted smallint DEFAULT 0,
    annotation_status character varying(32) DEFAULT 'UNLABELED'::character varying,
    annotation_revision integer DEFAULT 0,
    latest_candidate_id bigint,
    reviewed_time timestamp without time zone,
    reviewer_id character varying(64),
    capture_job_id bigint,
    source_ref_id character varying(255),
    source_camera_name character varying(128),
    source_frame_key character varying(255),
    source_frame_index bigint,
    source_frame_time timestamp without time zone,
    source_meta_json text,
    dataset_version_id bigint,
    task_type character varying(32) DEFAULT 'DETECTION'::character varying,
    sample_role character varying(32) DEFAULT 'UNLABELED'::character varying,
    sample_status character varying(32) DEFAULT 'RAW'::character varying,
    review_status character varying(32) DEFAULT 'PENDING'::character varying,
    annotation_type character varying(32) DEFAULT 'BOX'::character varying,
    quality_score numeric(8,4),
    phash character varying(128)
);


