--

CREATE TABLE unix_tenant_202605.video_ai_media_server (
    id bigint NOT NULL,
    server_code character varying(128) NOT NULL,
    server_name character varying(128) NOT NULL,
    server_type character varying(32) DEFAULT 'ZLM'::character varying,
    stream_role character varying(32) DEFAULT 'BOTH'::character varying,
    media_server_id character varying(128),
    group_name character varying(128) DEFAULT 'default'::character varying,
    region character varying(128),
    zone character varying(128),
    protocol character varying(16) DEFAULT 'http'::character varying,
    server_ip character varying(128),
    api_port integer DEFAULT 80,
    http_port integer DEFAULT 80,
    https_port integer DEFAULT 443,
    rtmp_port integer DEFAULT 1935,
    rtsp_port integer DEFAULT 554,
    rtp_proxy_port integer,
    rtc_port integer,
    api_base_url character varying(800),
    public_base_url character varying(800),
    internal_base_url character varying(800),
    secret character varying(512),
    enabled smallint DEFAULT 1,
    priority integer DEFAULT 100,
    weight integer DEFAULT 100,
    max_pull_streams integer DEFAULT 0,
    active_pull_streams integer DEFAULT 0,
    max_push_streams integer DEFAULT 0,
    active_push_streams integer DEFAULT 0,
    max_viewers integer DEFAULT 0,
    online_viewers integer DEFAULT 0,
    cpu_usage numeric(8,2),
    memory_usage numeric(8,2),
    bandwidth_in bigint,
    bandwidth_out bigint,
    load_score numeric(10,4) DEFAULT 0,
    status character varying(32) DEFAULT 'UNKNOWN'::character varying,
    health_status character varying(32) DEFAULT 'UNKNOWN'::character varying,
    last_heartbeat timestamp without time zone,
    last_probe_time timestamp without time zone,
    zlm_version character varying(128),
    capabilities_json text,
    labels_json text,
    config_json text,
    error_message character varying(1000),
    tenant_id character varying(64),
    creator_id character varying(64),
    create_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    deleted smallint DEFAULT 0
);


