    instance_key character varying(100) NOT NULL,
    platform_device_id character varying(100) NOT NULL,
    channel_id character varying(100) NOT NULL,
    channel_name character varying(200) DEFAULT NULL::character varying,
    channel_status character varying(50) DEFAULT NULL::character varying,
    channel_type character varying(50) DEFAULT NULL::character varying,
    parent_id character varying(100) DEFAULT NULL::character varying,
    manufacturer character varying(100) DEFAULT NULL::character varying,
    model character varying(100) DEFAULT NULL::character varying,
    owner character varying(100) DEFAULT NULL::character varying,
    civil_code character varying(100) DEFAULT NULL::character varying,
    address character varying(200) DEFAULT NULL::character varying,
    parental integer DEFAULT 0,
    safety_way integer,
    register_way integer,
    secrecy integer,
    ip_address character varying(50) DEFAULT NULL::character varying,
    port integer,
    longitude character varying(50) DEFAULT NULL::character varying,
    latitude character varying(50) DEFAULT NULL::character varying,
    ptz_type integer DEFAULT 0,
    position_type integer,
    stream_id character varying(100) DEFAULT NULL::character varying,
    gb_stream_id character varying(100) DEFAULT NULL::character varying,
    has_audio smallint DEFAULT '0'::smallint,
    camera_index_code character varying(100) DEFAULT NULL::character varying,
    channel_no character varying(20) DEFAULT NULL::character varying,
    camera_type integer,
    ptz smallint,
    capability_set character varying(100) DEFAULT NULL::character varying,
    install_location character varying(200) DEFAULT NULL::character varying,
    channel_code character varying(100) DEFAULT NULL::character varying,
    channel_seq integer,
    encode_format character varying(50) DEFAULT NULL::character varying,
    resolution character varying(50) DEFAULT NULL::character varying,
    capabilities text,
    stream_config text,
    ext_field1 character varying(500) DEFAULT NULL::character varying,
    ext_field2 character varying(500) DEFAULT NULL::character varying,
    ext_field3 text,
    enabled smallint DEFAULT '1'::smallint,
    create_time timestamp(6) without time zone DEFAULT now(),
    update_time timestamp(6) without time zone DEFAULT now(),
    create_id character varying(100) DEFAULT NULL::character varying,
    update_id character varying(100) DEFAULT NULL::character varying,
    tenant_id character varying(12) DEFAULT NULL::character varying
);


