--
-- Name: video_sdk_record_task; Type: TABLE; Schema: unix_tenant_202605; Owner: -
--

CREATE TABLE unix_tenant_202605.video_sdk_record_task (
    id character varying(64) NOT NULL,
    tenant_id character varying(64) NOT NULL,
    instance_key character varying(200) NOT NULL,
    device_id character varying(200) NOT NULL,
    channel_id character varying(200) NOT NULL,
    task_name character varying(200),
    mode character varying(64) NOT NULL,
    start_time bigint,
    end_time bigint,
    status character varying(64) NOT NULL,
    progress integer,
    message character varying(1200),
    gateway_job_id character varying(64),
    result_json text,
    created_by character varying(64),
    created_at bigint NOT NULL,
    updated_at bigint NOT NULL,
    next_poll_at bigint NOT NULL,
    lease_until bigint NOT NULL,
    lease_owner character varying(64),
    cancel_requested integer NOT NULL
);


