-- ISUP durable callback receipts.
CREATE TABLE unix_tenant_202605.video_sdk_alarm_receipt (
  id varchar(64) NOT NULL,
  tenant_id varchar(100) NOT NULL,
  instance_key varchar(100) NOT NULL,
  device_id varchar(100) NOT NULL,
  channel_id varchar(100) NOT NULL DEFAULT '',
  event_id varchar(200) NOT NULL,
  event_kind varchar(100) NOT NULL,
  image_fingerprint varchar(64) NOT NULL DEFAULT '',
  status varchar(16) NOT NULL DEFAULT 'pending',
  payload_json text NOT NULL,
  result_json text,
  log_persisted integer NOT NULL DEFAULT 0,
  flow_dispatched integer NOT NULL DEFAULT 0,
  attempts integer NOT NULL DEFAULT 0,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  next_attempt_at bigint NOT NULL DEFAULT 0,
  lease_until bigint NOT NULL DEFAULT 0,
  lease_owner varchar(64) NOT NULL DEFAULT ''
);

-- Reviewed V2026101304 motion process projection; no business rows.
CREATE TABLE unix_tenant_202605.video_sdk_alarm_process (
  id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(100) NOT NULL,
  instance_key VARCHAR(100) NOT NULL,
  device_id VARCHAR(100) NOT NULL,
  channel_id VARCHAR(100) NOT NULL,
  event_kind VARCHAR(16) NOT NULL DEFAULT 'motion',
  row_kind VARCHAR(16) NOT NULL,
  state VARCHAR(16) NOT NULL,
  current_process_id VARCHAR(64),
  first_time BIGINT NOT NULL DEFAULT 0,
  last_time BIGINT NOT NULL DEFAULT 0,
  first_received_at BIGINT NOT NULL DEFAULT 0,
  last_received_at BIGINT NOT NULL DEFAULT 0,
  event_count BIGINT NOT NULL DEFAULT 0,
  first_event_id VARCHAR(200) NOT NULL DEFAULT '',
  last_event_id VARCHAR(200) NOT NULL DEFAULT '',
  start_observed INTEGER NOT NULL DEFAULT 0,
  stop_observed INTEGER NOT NULL DEFAULT 0,
  closed_at BIGINT NOT NULL DEFAULT 0,
  close_reason VARCHAR(32) NOT NULL DEFAULT '',
  created_at BIGINT NOT NULL,
  updated_at BIGINT NOT NULL,
  CONSTRAINT video_sdk_alarm_process_pkey PRIMARY KEY (id),
  CONSTRAINT uk_video_alarm_process_scope UNIQUE (id,tenant_id,instance_key,device_id,channel_id),
  CONSTRAINT ck_video_alarm_process_kind CHECK (event_kind='motion' AND row_kind IN ('guard','process')),
  CONSTRAINT ck_video_alarm_process_state CHECK ((row_kind='guard' AND state='guard') OR (row_kind='process' AND state IN ('active','unknown','ended','unknown_gap'))),
  CONSTRAINT ck_video_alarm_process_count CHECK (event_count>=0 AND first_time>=0 AND last_time>=first_time),
  CONSTRAINT ck_video_alarm_process_flags CHECK (start_observed IN (0,1) AND stop_observed IN (0,1))
);
CREATE TABLE unix_tenant_202605.video_sdk_alarm_process_member (
  receipt_id VARCHAR(64) NOT NULL,
  process_id VARCHAR(64) NOT NULL,
  tenant_id VARCHAR(100) NOT NULL,
  instance_key VARCHAR(100) NOT NULL,
  device_id VARCHAR(100) NOT NULL,
  channel_id VARCHAR(100) NOT NULL,
  event_id VARCHAR(200) NOT NULL,
  source_event_id VARCHAR(256),
  evidence_id VARCHAR(64),
  alarm_state VARCHAR(16) NOT NULL,
  alarm_time BIGINT NOT NULL,
  received_at BIGINT NOT NULL,
  active_post_count BIGINT,
  CONSTRAINT video_alarm_process_member_pkey PRIMARY KEY (receipt_id),
  CONSTRAINT fk_video_alarm_member_scope FOREIGN KEY (process_id,tenant_id,instance_key,device_id,channel_id)
    REFERENCES unix_tenant_202605.video_sdk_alarm_process (id,tenant_id,instance_key,device_id,channel_id),
  CONSTRAINT ck_video_alarm_member_state CHECK (alarm_state IN ('start','stop','unknown')),
  CONSTRAINT ck_video_alarm_member_count CHECK (active_post_count IS NULL OR active_post_count>=0)
);

-- Reviewed V2026110301: no tenant credentials or identity bindings are seeded.
CREATE TABLE unix_tenant_202605.iot_wechat_login_config (
  tenant_id VARCHAR(100) COLLATE "C" NOT NULL,
  account_name VARCHAR(100),
  app_id VARCHAR(128) COLLATE "C",
  app_secret TEXT,
  callback_token TEXT,
  encoding_aes_key TEXT,
  account_qr_url VARCHAR(2048),
  capability_mode VARCHAR(20) NOT NULL DEFAULT 'MESSAGE_CODE',
  login_mode VARCHAR(20) NOT NULL DEFAULT 'BOUND_USER',
  enabled BOOLEAN NOT NULL DEFAULT FALSE,
  binding_enabled BOOLEAN NOT NULL DEFAULT TRUE,
  demo_user_union_id VARCHAR(100) COLLATE "C",
  expire_seconds INTEGER NOT NULL DEFAULT 180,
  config_version BIGINT NOT NULL DEFAULT 1,
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT iot_wechat_login_config_pkey PRIMARY KEY (tenant_id),
  CONSTRAINT ck_wechat_login_capability CHECK (capability_mode IN ('AUTO','SCENE_QR','MESSAGE_CODE')),
  CONSTRAINT ck_wechat_login_mode CHECK (login_mode IN ('BOUND_USER','DEMO_ACCOUNT')),
  CONSTRAINT ck_wechat_login_expiry CHECK (expire_seconds BETWEEN 60 AND 600),
  CONSTRAINT ck_wechat_login_version CHECK (config_version >= 1)
);

CREATE TABLE unix_tenant_202605.iot_user_wechat_binding (
  id VARCHAR(32) COLLATE "C" NOT NULL,
  tenant_id VARCHAR(100) COLLATE "C" NOT NULL,
  app_id VARCHAR(128) COLLATE "C" NOT NULL,
  openid VARCHAR(128) COLLATE "C" NOT NULL,
  user_union_id VARCHAR(100) COLLATE "C" NOT NULL,
  create_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  update_time TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT iot_user_wechat_binding_pkey PRIMARY KEY (id),
  CONSTRAINT uk_wechat_binding_identity UNIQUE (tenant_id,app_id,openid),
  CONSTRAINT uk_wechat_binding_account UNIQUE (tenant_id,app_id,user_union_id)
);
CREATE INDEX idx_wechat_binding_unsubscribe ON unix_tenant_202605.iot_user_wechat_binding (app_id,openid);
